#!/usr/bin/env python3
"""Build the Chinese-calendar reference data from the Hong Kong Observatory conversion tables.

Source: Hong Kong Observatory, "Gregorian-Lunar Calendar Conversion Table" 1901-2100,
https://www.hko.gov.hk/en/gts/time/conversion1_text.htm (one text file per year,
https://www.hko.gov.hk/en/gts/time/calendar/text/files/T<year>e.txt). Download them into a
directory and pass it with --hko.

1900 is not covered by HKO. Its new year (1900-01-31) was computed with Swiss Ephemeris (new
moon of the month holding Yushui, Beijing local time) and agrees with the published 1900 almanac
date; the same computation reproduces all 200 HKO dates except the three years where the simple
Yushui rule is known to fail (1985, 2034, 2053), for which HKO is authoritative.

Outputs:
  * --resource : chinese_new_year.txt bundled in :core (and copied by the Swift package):
                 one 'year YYYY-MM-DD' line per year 1900-2100.
  * --golden   : testdata/chinese_calendar.json - new-year dates plus the date (Hong Kong /
                 China time, UTC+8) of every one of the 24 solar terms 1901-2100, which the engines
                 use to test their Sun-longitude based solar terms (Lichun etc.).
"""

from __future__ import annotations

import argparse
import json
import re
import sys

TERMS = {  # HKO English name -> (apparent solar longitude, pinyin, hanzi)
    "Moderate Cold": (285, "Xiaohan", "小寒"), "Severe Cold": (300, "Dahan", "大寒"),
    "Spring Commences": (315, "Lichun", "立春"), "Spring Showers": (330, "Yushui", "雨水"),
    "Insects Waken": (345, "Jingzhe", "惊蛰"), "Vernal Equinox": (0, "Chunfen", "春分"),
    "Bright & Clear": (15, "Qingming", "清明"), "Corn Rain": (30, "Guyu", "谷雨"),
    "Summer Commences": (45, "Lixia", "立夏"), "Corn Forms": (60, "Xiaoman", "小满"),
    "Corn on Ear": (75, "Mangzhong", "芒种"), "Summer Solstice": (90, "Xiazhi", "夏至"),
    "Moderate Heat": (105, "Xiaoshu", "小暑"), "Great Heat": (120, "Dashu", "大暑"),
    "Autumn Commences": (135, "Liqiu", "立秋"), "End of Heat": (150, "Chushu", "处暑"),
    "White Dew": (165, "Bailu", "白露"), "Autumnal Equinox": (180, "Qiufen", "秋分"),
    "Cold Dew": (195, "Hanlu", "寒露"), "Frost": (210, "Shuangjiang", "霜降"),
    "Winter Commences": (225, "Lidong", "立冬"), "Light Snow": (240, "Xiaoxue", "小雪"),
    "Heavy Snow": (255, "Daxue", "大雪"), "Winter Solstice": (270, "Dongzhi", "冬至"),
}
DATE = re.compile(r"^(\d{4})/(\d{1,2})/(\d{1,2})\s+(.*)$")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--hko", required=True)
    ap.add_argument("--resource", required=True)
    ap.add_argument("--golden", required=True)
    args = ap.parse_args()

    cny = {1900: "1900-01-31"}
    terms = []
    for year in range(1901, 2101):
        text = open(f"{args.hko}/T{year}e.txt", encoding="latin-1").read()
        found = 0
        for line in text.splitlines():
            m = DATE.match(line.strip())
            if not m:
                continue
            date = f"{int(m.group(1)):04d}-{int(m.group(2)):02d}-{int(m.group(3)):02d}"
            rest = m.group(4).rstrip()
            if re.match(r"1st Lunar Month", rest, re.I) and int(m.group(1)) == year:
                cny.setdefault(year, date)
            for name, (lon, pinyin, hanzi) in TERMS.items():
                if rest.endswith(name):
                    terms.append({"date": date, "longitude": lon, "name": pinyin, "hanzi": hanzi})
                    found += 1
        if found != 24:
            raise SystemExit(f"{year}: found {found} solar terms, expected 24")
        if year not in cny:
            raise SystemExit(f"{year}: no 1st lunar month")

    with open(args.resource, "w", encoding="ascii") as fh:
        fh.write("# Chinese New Year (1st day of the 1st lunar month), China time. GENERATED by\n")
        fh.write("# testdata/tools/make_chinese_calendar.py from Hong Kong Observatory tables (1900 computed).\n")
        for year in range(1900, 2101):
            fh.write(f"{year} {cny[year]}\n")

    doc = {
        "description": "Chinese calendar reference data. newYear: first day of the lunar year. "
                       "solarTerms: civil date in China/Hong Kong time (UTC+8) on which the apparent "
                       "Sun reaches each of the 24 term longitudes.",
        "source": "Hong Kong Observatory Gregorian-Lunar Calendar Conversion Tables 1901-2100; "
                  "1900 new year computed with Swiss Ephemeris",
        "generator": "testdata/tools/make_chinese_calendar.py",
        "newYear": {str(y): cny[y] for y in range(1900, 2101)},
        "solarTerms": terms,
    }
    with open(args.golden, "w", encoding="utf-8") as fh:
        json.dump(doc, fh, ensure_ascii=False, indent=0)
        fh.write("\n")
    print(f"wrote {len(cny)} new years and {len(terms)} solar terms")
    return 0


if __name__ == "__main__":
    sys.exit(main())
